import { readFile } from 'node:fs/promises'
import type { AgentRunStatus, ReportCommand, ReportFileChange, ReportTests, RunReport, ToolRun } from '@ai-workspace/shared'
import type { AgentRepository, FileSnapshot } from '@ai-workspace/storage'
import { decodeUtf8, sha256 } from '../code/file-service'
import { resolveInRoot } from '../code/path-safety'
import { isTestCommand } from './command-classifier'
import { diffStats } from './unified-diff'

/**
 * The run report (ADR-044). It is generated by OUR code from the audit log and from the disk after the
 * run - never by the model. The model's own closing words are shown separately, labelled as the model's,
 * and nothing it says can change a fact here: "tests passed" appears only if a test command actually ran
 * to completion and exited 0; "files changed" are re-read from disk and compared with the agent's last write.
 */

export interface ReportInput {
  runStatus: AgentRunStatus
  toolRuns: ToolRun[]
  snapshots: FileSnapshot[]
  /** Absolute workspace root, for re-reading the files. */
  root: string
  /** The model's closing text (narrative). Only used to extract its "Remaining concerns". */
  modelText: string
  changedByCommands: string[]
  repo?: AgentRepository
}

function parseInput(row: ToolRun): Record<string, unknown> {
  try {
    const value = JSON.parse(row.input) as unknown
    return typeof value === 'object' && value !== null ? (value as Record<string, unknown>) : {}
  } catch {
    return {}
  }
}

const normalizePath = (value: unknown): string | null =>
  typeof value === 'string' && value.trim() !== '' ? value.trim().replace(/\\/g, '/').replace(/^\.\//, '') : null

/** True when the row is a command that actually started (not refused, not blocked before running). */
function commandStarted(row: ToolRun): boolean {
  if (row.toolId !== 'terminal.execute') return false
  if (row.status === 'denied') return false
  if (row.status === 'error' && (row.decisionSource === 'not-asked' || row.decisionSource === null)) return false
  if (row.status === 'cancelled' && row.finishedAt !== null && row.decisionSource === 'cancelled') return false
  return row.status === 'ok' || row.status === 'error' || row.status === 'cancelled' || row.status === 'running'
}

function decodeText(buffer: Buffer | null): string | null {
  if (buffer === null) return ''
  return decodeUtf8(buffer)
}

async function readDisk(root: string, path: string): Promise<{ exists: boolean; hash: string | null; text: string | null }> {
  try {
    const resolved = await resolveInRoot(root, path)
    const bytes = await readFile(resolved.absolutePath)
    const text = decodeUtf8(bytes)
    // Strip a BOM so counts compare text, like the editor does.
    return { exists: true, hash: sha256(bytes), text: text === null ? null : text.replace(/^﻿/, '') }
  } catch {
    return { exists: false, hash: null, text: null }
  }
}

export async function describeSnapshot(root: string, snap: FileSnapshot): Promise<ReportFileChange> {
  const disk = await readDisk(root, snap.path)
  const before = decodeText(snap.beforeContent)
  const beforeText = before === null ? null : before.replace(/^﻿/, '')
  const kind = snap.beforeContent === null ? 'created' : 'modified'
  let added = 0
  let removed = 0
  let note: string | null = null
  if (snap.revertedAt !== null) {
    note = 'reverted by you'
  } else if (!disk.exists) {
    note = 'the file no longer exists on disk'
    if (beforeText !== null) removed = diffStats(beforeText, '').removed
  } else if (disk.text === null || beforeText === null) {
    note = 'binary or non-UTF-8 content: line counts unavailable'
  } else {
    const stats = diffStats(beforeText, disk.text)
    added = stats.added
    removed = stats.removed
  }
  const verified = snap.revertedAt === null && disk.exists && disk.hash === snap.afterHash
  if (!verified && note === null && disk.exists) note = 'the file on disk differs from the last write the agent made (edited again afterwards)'
  return { path: snap.path, kind, added, removed, verified, note, reverted: snap.revertedAt !== null }
}

/** Extracts what the model wrote after a "Remaining concerns" heading, verbatim. */
export function extractModelConcerns(text: string): string | null {
  const match = /(?:^|\n)[ \t]{0,3}(?:#{1,6}[ \t]*|\*\*|_{2})?[ \t]*remaining[ \t]+concerns?[ \t]*(?:\*\*|__)?[ \t]*:?(?:\*\*|__)?[ \t]*([\s\S]*)$/i.exec(text)
  if (!match) return null
  const body = (match[1] ?? '').trim()
  if (body === '') return null
  return body.length > 1500 ? `${body.slice(0, 1500)}…` : body
}

function buildTests(rows: ToolRun[], changeRows: ToolRun[]): ReportTests {
  const started = rows.filter(commandStarted)
  const testRows = started.filter((r) => {
    const command = parseInput(r)['command']
    return typeof command === 'string' && isTestCommand(command)
  })
  const lastTest = testRows.at(-1)
  if (!lastTest) {
    const lookalike = started.find((r) => {
      const command = parseInput(r)['command']
      return typeof command === 'string' && /\b(?:test|tests|vitest|jest|pytest|mocha|spec)\b/i.test(command)
    })
    if (lookalike) {
      return {
        status: 'unverified',
        command: String(parseInput(lookalike)['command']),
        exitCode: lookalike.exitCode,
        editsAfterTests: false,
        detail:
          'A command that mentions tests ran, but its shape (a pipe, ";", "||", a redirect or a background job) means its exit code does not prove the tests passed. It is not counted as a test run.',
      }
    }
    return { status: 'not_run', command: null, exitCode: null, editsAfterTests: false, detail: 'No test command was run.' }
  }
  const command = String(parseInput(lastTest)['command'])
  const editsAfterTests = changeRows.some((r) => r.seq > lastTest.seq)
  if (lastTest.status === 'cancelled' || lastTest.exitCode === null) {
    const why = /timed out/i.test(lastTest.summary) ? 'timed out' : lastTest.status === 'cancelled' ? 'was cancelled' : 'did not finish'
    return { status: 'unverified', command, exitCode: null, editsAfterTests, detail: `The test command ${why}, so there is no test result.` }
  }
  if (lastTest.exitCode === 0 && lastTest.status === 'ok') {
    return {
      status: 'passed',
      command,
      exitCode: 0,
      editsAfterTests,
      detail: editsAfterTests
        ? 'The last test run exited 0, but files were changed after it; those changes were not covered by a test run.'
        : 'The last test run exited 0.',
    }
  }
  return { status: 'failed', command, exitCode: lastTest.exitCode, editsAfterTests, detail: `The last test run exited ${lastTest.exitCode}.` }
}

export async function buildRunReport(input: ReportInput): Promise<RunReport> {
  const rows = input.toolRuns
  const filesInspected: string[] = []
  for (const row of rows) {
    if (row.toolId !== 'filesystem.read' || row.status !== 'ok') continue
    const path = normalizePath(parseInput(row)['path'])
    if (path && !filesInspected.includes(path)) filesInspected.push(path)
  }

  const filesChanged: ReportFileChange[] = []
  for (const snap of input.snapshots) filesChanged.push(await describeSnapshot(input.root, snap))

  const changeRows = rows.filter((r) => (r.toolId === 'filesystem.write' || r.toolId === 'filesystem.patch') && r.status === 'ok')

  const commands: ReportCommand[] = rows.filter(commandStarted).map((row) => {
    const command = String(parseInput(row)['command'] ?? row.label)
    const timedOut = /timed out/i.test(row.summary)
    return {
      command,
      exitCode: row.exitCode,
      status: row.status,
      durationMs: row.durationMs,
      isTest: isTestCommand(command),
      note: timedOut ? 'timed out and was killed' : row.status === 'cancelled' ? 'cancelled' : null,
    }
  })

  const refused = rows
    .filter((r) => r.status === 'denied' || (r.status === 'cancelled' && r.decisionSource === 'cancelled'))
    .map((r) => ({
      label: r.label,
      reason: r.status === 'cancelled' ? 'cancelled before it ran' : r.decisionSource === 'prompt-deny' ? 'denied by you' : 'blocked (not available in this mode or for this agent)',
    }))

  const stoppedBy: RunReport['stoppedBy'] =
    input.runStatus === 'completed'
      ? 'finished'
      : input.runStatus === 'step_limit'
        ? 'step_limit'
        : input.runStatus === 'timeout'
          ? 'timeout'
          : input.runStatus === 'cancelled'
            ? 'cancelled'
            : 'error'

  return {
    filesInspected,
    filesChanged,
    changedByCommands: input.changedByCommands.slice(0, 30),
    commands,
    tests: buildTests(rows, changeRows),
    refused,
    toolCalls: rows.length,
    toolErrors: rows.filter((r) => r.status === 'error').length,
    stoppedBy,
    modelConcerns: extractModelConcerns(input.modelText),
  }
}
